class ListNode(var `val`: Int) {
    var next: ListNode? = null
}

fun reverseList(head: ListNode?): ListNode? {
    var prev: ListNode? = null
    var curr = head
    while (curr != null) {
        val next = curr.next     // 1. save the rest of the list
        curr.next = prev         // 2. reverse the pointer
        prev = curr              // 3. move prev forward
        curr = next              // 4. move curr forward
    }
    return prev                  // new head
}
// Time: O(n)   Space: O(1)

fun reverseListRecursive(head: ListNode?): ListNode? {
    if (head?.next == null) return head
    val newHead = reverseListRecursive(head.next)
    head.next!!.next = head      // make the next node point back to head
    head.next = null             // head becomes the tail
    return newHead
}
// Time: O(n)   Space: O(n) call stack

fun reverseKGroup(head: ListNode?, k: Int): ListNode? {
    // check if at least k nodes remain
    var check = head
    var count = 0
    while (check != null && count < k) {
        check = check.next
        count++
    }
    if (count < k) return head          // fewer than k nodes, keep as is

    // reverse k nodes
    var prev: ListNode? = null
    var curr = head
    repeat(k) {
        val next = curr!!.next
        curr!!.next = prev
        prev = curr
        curr = next
    }
    // head is now the tail of this group, connect it to the next reversed group
    head!!.next = reverseKGroup(curr, k)
    return prev
}
// Time: O(n)   Space: O(n / k) recursion stack

fun reverseKGroupIterative(head: ListNode?, k: Int): ListNode? {
    val dummy = ListNode(0)
    dummy.next = head
    var groupPrev: ListNode = dummy

    while (true) {
        // find the k-th node from groupPrev
        var kth: ListNode? = groupPrev
        repeat(k) { kth = kth?.next }
        if (kth == null) break

        val groupNext = kth!!.next
        var prev: ListNode? = groupNext
        var curr = groupPrev.next
        while (curr !== groupNext) {
            val next = curr!!.next
            curr.next = prev
            prev = curr
            curr = next
        }
        val tail = groupPrev.next!!        // old first node is the new tail
        groupPrev.next = kth               // k-th node is the new first node
        groupPrev = tail
    }
    return dummy.next
}
// Time: O(n)   Space: O(1)

fun swapPairs(head: ListNode?): ListNode? {
    val dummy = ListNode(0)
    dummy.next = head
    var prev: ListNode = dummy
    while (prev.next?.next != null) {
        val first = prev.next!!
        val second = first.next!!
        first.next = second.next        // first skips over second
        second.next = first             // second points back to first
        prev.next = second              // connect previous part
        prev = first                    // first is now the tail of the pair
    }
    return dummy.next
}
// Time: O(n)   Space: O(1)
// Same as reverseKGroup with k = 2

fun rotateRight(head: ListNode?, k: Int): ListNode? {
    if (head?.next == null || k == 0) return head
    // 1. find length and tail
    var tail = head
    var length = 1
    while (tail!!.next != null) {
        tail = tail.next
        length++
    }
    // 2. make it circular
    tail.next = head
    // 3. find the new tail: (length - k % length - 1) steps from head
    val steps = length - k % length - 1
    var newTail = head
    repeat(steps) { newTail = newTail!!.next }
    // 4. break the circle
    val newHead = newTail!!.next
    newTail.next = null
    return newHead
}
// Time: O(n)   Space: O(1)

fun reverseAlternateK(head: ListNode?, k: Int): ListNode? {
    var curr = head
    var prevTail: ListNode? = null
    var newHead: ListNode? = null

    while (curr != null) {
        val groupStart = curr
        var prev: ListNode? = null
        var count = 0
        // reverse up to k nodes
        while (curr != null && count < k) {
            val next = curr.next
            curr.next = prev
            prev = curr
            curr = next
            count++
        }
        if (newHead == null) newHead = prev
        prevTail?.next = prev
        groupStart.next = curr             // reversed group's tail points on
        // skip the next k nodes without reversing
        var skipped = 0
        var tail = groupStart
        while (curr != null && skipped < k) {
            tail = curr
            curr = curr.next
            skipped++
        }
        prevTail = tail
    }
    return newHead
}
// Time: O(n)   Space: O(1)

fun addTwoNumbersForward(l1: ListNode?, l2: ListNode?): ListNode? {
    fun reverse(head: ListNode?): ListNode? {
        var prev: ListNode? = null
        var curr = head
        while (curr != null) {
            val next = curr.next
            curr.next = prev
            prev = curr
            curr = next
        }
        return prev
    }
    var a = reverse(l1)
    var b = reverse(l2)
    var result: ListNode? = null
    var carry = 0
    while (a != null || b != null || carry != 0) {
        val sum = (a?.`val` ?: 0) + (b?.`val` ?: 0) + carry
        carry = sum / 10
        val node = ListNode(sum % 10)
        node.next = result            // build the answer backwards
        result = node
        a = a?.next
        b = b?.next
    }
    return result
}
// Time: O(n + m)   Space: O(1) extra

fun reverseWithStack(head: ListNode?): ListNode? {
    val stack = ArrayDeque<ListNode>()
    var curr = head
    while (curr != null) {
        stack.addLast(curr)
        curr = curr.next
    }
    val dummy = ListNode(0)
    var tail = dummy
    while (stack.isNotEmpty()) {
        tail.next = stack.removeLast()
        tail = tail.next!!
    }
    tail.next = null                       // avoid creating a cycle
    return dummy.next
}
// Time: O(n)   Space: O(n)   -> this is NOT in place
